  x.trace.push({at:new Date().toISOString(),stage:'KNOWLEDGE_HTTP',decision:r.is_mock === true ? 'MOCK' : 'RECEIVED',reason_codes:[]});
} else {
  x.knowledge = null;
  x.versions.knowledge = 'unavailable';
  x.trace.push({at:new Date().toISOString(),stage:'KNOWLEDGE_HTTP',decision:'REVIEW',reason_codes:['KNOWLEDGE_ENDPOINT_FAILED_OR_INVALID']});
}
